scripts.world.joiner.probe:
{
  "schema": 1,
  "timeout_ms": 420000,
  "step_timeout_ms": 120000,
  "label_dump": {
    "every_ms": 5000
  },
  "steps": [
    {
      "op": "wait",
      "service": "Running",
      "within_ms": 180000
    },
    {
      "op": "wait",
      "service": "Running",
      "lockstep_frame_at_least": 1560,
      "ai_held_peer_ids": [],
      "within_ms": 180000
    },
    {
      "op": "menu",
      "command": "video_mark world-playing",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "world-playing",
      "scope": "menu"
    },
    {
      "op": "wait",
      "service": "Running",
      "elapsed_ms": 3000,
      "ai_held_peer_ids": [],
      "within_ms": 120000
    },
    {
      "op": "menu",
      "command": "video_mark hang-host",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "scope": "menu",
      "screen": "MultiplayerScreen",
      "control": "LabelMultiplayerLandingStatus",
      "text_contains": "The host stopped responding. The round has ended; the world continues from its last save when the host is back.",
      "within_ms": 60000
    },
    {
      "op": "menu",
      "command": "video_mark host-unresponsive",
      "capture_screen": "MultiplayerScreen"
    },
    {
      "op": "wait",
      "elapsed_ms": 1200,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "host-unresponsive",
      "scope": "menu"
    },
    {
      "op": "assert_control",
      "control": "LabelMultiplayerLandingStatus",
      "scope": "menu",
      "text_contains": "The host stopped responding. The round has ended; the world continues from its last save when the host is back.",
      "fits": true
    },
    {
      "op": "assert_control",
      "control": "ButtonMultiplayerReconnect",
      "scope": "menu",
      "text_contains": "Rejoin Match"
    },
    {
      "op": "wait_file",
      "path": "{PROBE_DIR_host}/injected-suspend.json",
      "scope": "menu",
      "within_ms": 120000
    },
    {
      "op": "wait",
      "elapsed_ms": 3000,
      "scope": "menu"
    },
    {
      "op": "menu",
      "command": "activate ButtonMultiplayerReconnect"
    },
    {
      "op": "wait",
      "service": "Running",
      "within_ms": 180000
    },
    {
      "op": "wait",
      "service": "Running",
      "control": "LabelNetMatchStatus",
      "text_contains": "Everyone is connected",
      "equals": {
        "visible": true
      },
      "within_ms": 240000
    },
    {
      "op": "wait",
      "service": "Running",
      "elapsed_ms": 3000,
      "ai_held_peer_ids": [],
      "within_ms": 120000
    },
    {
      "op": "menu",
      "command": "video_mark world-continued",
      "capture_screen": "game"
    },
    {
      "op": "wait",
      "elapsed_ms": 6000,
      "scope": "menu"
    },
    {
      "op": "screenshot_pair",
      "name": "world-continued",
      "scope": "menu"
    },
    {
      "op": "signal",
      "name": "done",
      "scope": "menu"
    },
    {
      "op": "finish"
    }
  ]
}

